void pgdetach ( pp ) proc_t * pp ; { int stopped ; register proc_t * cp ; register proc_t * mp ; register struct pid * pgp ; ASSERT ( MUTEX_HELD ( & pidlock ) ) ; for ( cp = pp -> p_child ; cp ; cp = cp -> p_sibling ) { if ( ( pgp = cp -> p_pgidp ) -> pid_pgorphaned ) { continue ; } stopped = 0 ; mp = pgp -> pid_pglink ; ASSERT ( mp != NULL ) ; for ( ; ; ) { if ( ! stopped && mp != curproc ) { mutex_enter ( & mp -> p_lock ) ; stopped = jobstopped ( mp ) ; mutex_exit ( & mp -> p_lock ) ; } if ( ( mp = mp -> p_pglink ) == NULL ) { pgp -> pid_pgorphaned = 1 ; if ( stopped ) { sigtopg ( pgp , SIGHUP ) ; sigtopg ( pgp , SIGCONT ) ; } break ; } } } } 